contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _caller, address _newOwner) public payable {
        require(_caller != address(0));
        require(_caller != address(this));
        require(_caller != address(c));
        require(_caller != c.owner());
        require(_newOwner != address(0));

        c.transferOwnership(_caller); if (__ESBMC_reverted()) return;
        c.transferOwnership(_newOwner); if (__ESBMC_reverted()) return;

        address newOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(msg.sender == _caller || newOwner == _newOwner);
    }
}

